package com.asmj.marketplace.product.controller;import com.asmj.marketplace.common.response.ApiResponse;import com.asmj.marketplace.product.dto.ProductDtos.*;import com.asmj.marketplace.product.service.ProductService;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;
@RestController @RequestMapping("/api/products") @RequiredArgsConstructor public class ProductController{final ProductService s;String e(Authentication a){return a.getName();}@GetMapping public ApiResponse<?> products(){return ApiResponse.ok("",s.publicProducts());}@PreAuthorize("hasRole('VENDOR')") @GetMapping("/vendor")public ApiResponse<?> vp(Authentication a){return ApiResponse.ok("",s.vendorProducts(e(a)));}@PreAuthorize("hasRole('VENDOR')") @PostMapping("/vendor")public ApiResponse<?> create(Authentication a,@RequestBody ProductRequest r){return ApiResponse.ok("",s.save(e(a),r,null));}@PreAuthorize("hasRole('VENDOR')") @PutMapping("/vendor/{id}")public ApiResponse<?> edit(Authentication a,@PathVariable String id,@RequestBody ProductRequest r){return ApiResponse.ok("",s.save(e(a),r,id));}@PreAuthorize("hasAnyRole('USER','VENDOR','ADMIN')") @GetMapping("/cart")public ApiResponse<?> cart(Authentication a){return ApiResponse.ok("",s.cart(e(a)));}@PreAuthorize("hasAnyRole('USER','VENDOR','ADMIN')") @PostMapping("/cart")public ApiResponse<?> add(Authentication a,@RequestBody CartRequest r){return ApiResponse.ok("",s.add(e(a),r));}@PreAuthorize("hasAnyRole('USER','VENDOR','ADMIN')") @DeleteMapping("/cart")public ApiResponse<?> remove(Authentication a,@RequestParam String productId,@RequestParam(required=false)String variantId){return ApiResponse.ok("",s.remove(e(a),productId,variantId));}@PreAuthorize("hasAnyRole('USER','VENDOR','ADMIN')") @PostMapping("/checkout")public ApiResponse<?> checkout(Authentication a,@RequestBody CheckoutRequest r){return ApiResponse.ok("",s.checkout(e(a),r));}@PreAuthorize("isAuthenticated()") @GetMapping("/orders/my")public ApiResponse<?> my(Authentication a){return ApiResponse.ok("",s.myOrders(e(a)));}@PreAuthorize("hasRole('VENDOR')") @GetMapping("/orders/vendor")public ApiResponse<?> vo(Authentication a){return ApiResponse.ok("",s.vendorOrders(e(a)));}@PreAuthorize("hasAnyRole('VENDOR','ADMIN')") @PutMapping("/orders/{id}/status")public ApiResponse<?> status(Authentication a,@PathVariable String id,@RequestBody StatusRequest r){return ApiResponse.ok("",s.updateStatus(e(a),id,r));}}
